"""Hand-authored B003 G7 variants. Standard library only; never changes parents."""
import json, sys, hashlib
from datetime import datetime, timezone, timedelta
from pathlib import Path
from collections import Counter
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'scripts'))
from verify_pilot_variants import check_spec
P=[json.loads(s) for s in (ROOT/'data/variants/batches/b003/parents_g7.jsonl').read_text(encoding='utf-8').splitlines()]
OUT=ROOT/'data/variants/batches/b003'
rows=[]
def add(i,q,opts,ans,sol,expr,optexprs,change,reason=None,difficulty=None,spec=None):
 p=P[i-1]
 if isinstance(opts,list):opts=dict(zip('ABCD',opts))
 if isinstance(optexprs,list):optexprs=dict(zip('ABCD',optexprs))
 s=spec or {'kind':'derived_value','derived_expr':expr,'option_exprs':optexprs,'derivation':sol}
 r={'id':f'EMB-V-B003-G7-{i:03d}','parent_id':p['id'],'family_id':p['family_id'],'source_type':'variant','question':q,'options':opts,'answer':ans,'grade':7,'module':p['module'],'knowledge_point':p['knowledge_point'],'difficulty':difficulty or p['difficulty'],'input_modality':'text','image_assets':[],'solution':sol,'change_description':change,'source':{k:p.get('source_'+k) for k in ['id','title','url','ref']},'generation_metadata':{'agent':'finish_variants_g7','model':'inherited_parent_model','generated_at':datetime.now(timezone(timedelta(hours=8))).isoformat()},'difficulty_annotation':{'reason':reason or '依据本题条件进行概念辨析及所述计算；暂定难度，未经实测。','empirical':False},'risk_flags':['variant_draft','math_review_pending'],'status':'variant_draft_pending_review','verification_spec':s,'verification_note':'生成自检验证结构与明确算式，概念依据及题文对应仍需独立复核。'}
 matches,detail=check_spec(s)
 assert matches==[ans],(i,matches,ans,detail)
 assert i==len(rows)+1
 rows.append(r)
 if i%10==0:save()
def save():
 (OUT/'g7.jsonl').write_text(''.join(json.dumps(q,ensure_ascii=False)+'\n' for q in rows),encoding='utf-8')
 print(f'saved {len(rows)}',flush=True)

add(1,'用平面截正方体，要求截面是具有正面积的多边形。截面的边数最多是多少？',['4','5','6','7'],'C','截面每条边位于正方体的一个面上，每个面至多贡献一条边。正方体有6个面，故边数至多6；垂直于体对角线且通过其中心的平面可截得六边形，所以上界可达。','2+2+2',['4','5','6','7'],'将错误陈述辨析改为非退化正方体截面的最大边数，保留平面截几何体的推理。','需建立面数上界并说明六边形能够出现。')
add(2,'判断以下五个陈述，错误的有几个？①射线有两个端点；②角的大小不随所画两边的长短变化；③线段内只有有限个点；④两点间线段最短；⑤两个30°的角的和小于直角。',['1','2','3','4'],'B','射线只有一个端点，①错误；角度只取决于方向，②正确；线段内有无数个点，③错误；④正确；30°+30°=60°<90°，⑤正确。共2个错误。','sum((1!=2,0!=0,1!=0,0!=0,30+30>=90))',['1','2','3','4'],'将线段端点和锐角条件分别改为射线与两个30°，并改变有限点陈述。','需要同时辨析五项几何性质。')
add(3,'安装直线围栏时，工人先固定若干根位置不同的立柱，再沿确定的直线安装其余立柱。至少固定几根位置不同的立柱，才能唯一确定围栏所在直线？',['1根','2根','3根','4根'],'B','一个点能通过无数条直线；两个不同的点唯一确定一条直线。因此至少固定2根位置不同的立柱。','1+1',['1','2','3','4'],'把课桌前后定位改为立柱最少数量问题，增加唯一确定及不同位置条件。','从实际情境提取两点确定直线，实际为基础任务。','基础')
add(4,'已知∠A=42°24′，∠B=42.3°，∠C=42.45°，三个角从小到大的顺序是？',['A<B<C','B<A<C','C<A<B','B<C<A'],'B','42°24′=42+24/60=42.4°，所以42.3°<42.4°<42.45°，即B<A<C。',None,None,'改角度数值，使分秒转换后的次序改变。','需把度分与十进制度统一后比较。',spec={'kind':'ordering_values','values':{'A':'42+24/60','B':'42.3','C':'42.45'},'option_orders':{'A':['A','B','C'],'B':['B','A','C'],'C':['C','A','B'],'D':['B','C','A']}})
add(5,'A、C、B依次位于同一直线上，AC=3，CB=6。在直线AB同一侧分别作等边三角形ACM和CBN。令D为AN与CM的交点，E为MB与CN的交点，F为AN与MB的交点。以下结论中正确的有几个？①AN²=63；②DE∥AB；③∠AFB=60°；④CF平分∠AFB。',['1','2','3','4'],'C','∠ACN=∠MCB=120°，CA=CM且CN=CB，故△CAN≌△CMB，得到AN=MB及∠CAN=∠CMB。又△ADC≌△MEC，得CD=CE，而∠DCE=60°，所以△CDE等边且DE∥AB。以C为原点、AB为横轴，A=(-3,0)，B=(6,0)，N=(3,3√3)，所以AN²=6²+(3√3)²=63。由两交线方向可得∠AFB=120°，③错。C到FA与FB所在直线的距离分别等于C到AN与MB的距离；两全等三角形面积相等且AN=MB，故两距离相等。C在∠AFB内部，所以CF平分该角。①②④正确。','sum((6**2+27==63,60==60,180-60==60,63==63))',['1','2','3','4'],'核看原图后完整定义D、E、F及同侧等边三角形；增加AC=3、CB=6并改变长度和角度结论。','需全等、等边及角平分线距离判定联用。')
add(6,'在△ABC中，∠A=40°且AB=AC。把BC过C延长到P，把AB过B延长到M，把AC过C延长到N。内角∠ABC的平分线与外角∠ACP的平分线交于D；外角∠MBC的平分线与外角∠BCN的平分线交于E。判断：①AD∥BC；②BD⊥BE；③∠BDC=20°；④∠BEC=40°。正确的有几个？',['1','2','3','4'],'C','底角B=C=(180°-40°)/2=70°。BD与BC成35°，CD与CP成55°，所以∠BDC=55°-35°=20°。内外角平分线BD、BE互相垂直。D是B内角、C外角平分线交点，因此也在A外角平分线上，A外角的一半=70°，与底角相等，故AD∥BC。BE和CE的底角各为55°，∠BEC=180°-55°-55°=70°，④错误，前三项正确。','sum(((180-40)/2==(180-40)/2,35+55==90,55-35==20,180-55-55==40))',['1','2','3','4'],'补齐原图三个延长点与E的定义；加入顶角40°排除源解析未处理的等边特殊情形，改为数值结论。','需要内外角平分线和等腰三角形多步判断。')
add(7,'B、C是不同两点，A、D在直线BC同侧，AB⊥BC、DC⊥BC，且A、B、C、D按此顺序组成凸四边形。AB=5，CD=3。E在线段BC内部，AE平分∠BAD，DE平分∠ADC。求AD。',['6','7','8','10'],'C','过E向AD作垂线，垂足H。角平分线性质给EH=EB=EC。由直角三角形全等，AH=AB=5、DH=DC=3。凸四边形及两内角平分线相交保证H在线段AD上，故AD=AH+HD=8。也可验证取BC=√(8²-(5-3)²)=√60时条件可实现。','5+3',['6','7','8','10'],'原图关系改为完整凸四边形定义，给AB=5、CD=3求AD，保留角平分线垂距与全等主链。','需作辅助垂线并两次全等，不是一条已知公式直接代入。')
add(8,'矩形区域由0≤x≤10、0≤y≤5确定。点P从(0,4)出发，初始运动方向为向右下方，水平和竖直速度的绝对值相等。碰到一条边时按反射角等于入射角反弹；出发点不计作碰边。第2025次碰边时P的坐标为？',['(4,0)','(9,5)','(10,4)','(6,0)'],'C','依次碰边为(4,0)、(9,5)、(10,4)、(6,0)、(1,5)、(0,4)，随后方向也恢复，周期6。2025=6×337+3，所以第2025次与第三次相同，为(10,4)。路径从不经过顶点，无同时碰两边歧义。','(10,5-1)',['(4,0)','(9,5)','(10,4)','(6,0)'],'查看原图后将矩形8×4改成10×5，起点(0,3)改成(0,4)，次数改2025并明确斜率和计数规则。','需建立六次反射周期再取余。')
add(9,'两个角相等，且其中一个角的补角为126°。另一个角的补角是多少？',['54°','64°','126°','144°'],'C','原角=180°-126°=54°。另一个角也是54°，其补角=180°-54°=126°。','180-(180-126)',['54','64','126','144'],'把基本角性质选择改为同角补角的数值条件126°。','运用补角定义及等角补角相等。')
add(10,'把点(-2,3)向左平移5个单位，所得点的坐标为？',['(3,3)','(-7,3)','(-2,8)','(-2,-2)'],'B','向左平移只把横坐标减5，纵坐标不变；得到(-2-5,3)=(-7,3)。','(-2-5,3)',['(3,3)','(-7,3)','(-2,8)','(-2,-2)'],'起点改(-2,3)，方向改左，距离改5。','一次平移坐标计算。')
add(11,'C是线段AB的中点，AC=6.5厘米，AB的长度为？',['3.25厘米','6.5厘米','13厘米','19.5厘米'],'C','中点使AC=CB，所以AB=2AC=13厘米。','2*6.5',['3.25','6.5','13','19.5'],'已知AB=8改为AC=6.5并反求AB。','直接使用线段中点定义。')
add(12,'一根笔直的扇骨绕固定端点在平面内转动，扫过一个有正面积的扇形区域。这个区域在点、线、面、体的维数分类中是几维？',['0维','1维','2维','3维'],'C','扇骨是线段，绕端点运动扫出的区域是面，面为二维，因此选择2维。','1+1',['0','1','2','3'],'明确扇骨固定端点及扫出正面积，改问扫过区域维数，保留线动成面。','识别线动成面。')
add(13,'点P不在直线l上，A、B、C在l上，PA⊥l，PA=6厘米，PB=8厘米，PC=10厘米。点P到直线l的距离为？',['6厘米','8厘米','10厘米','24厘米'],'A','点到直线的距离是垂线段长度。PA⊥l，所以距离为PA=6厘米，斜线段PB、PC不表示该距离。','6',['6','8','10','24'],'把原性质陈述改为三条连线长度与垂足定义，保留点到直线距离辨析。','辨认垂线段。')
add(14,'M不在直线道路l上，A、B、C是l上三个不同站点。MA⊥l，MA=4千米，MB=5千米，MC=6千米，各连线均为可直接通行的道路。去最近站点的路程与去最远站点的路程相差多少？',['1千米','2千米','4千米','10千米'],'B','垂线段MA最短，为4千米；三给定路程中MC=6千米最大，差6-4=2千米。','max(4,5,6)-min(4,5,6)',['1','2','4','10'],'明确垂足及道路长度，改问最短与最远路程之差。','垂线段最短配合一次减法。')
add(15,'在π、√2、0.125、-∛64这四个实数中，无理数有几个？',['1','2','3','4'],'B','π和√2是无理数；0.125=1/8是有理数，-∛64=-4是整数。有2个无理数。√2若为既约有理数p/q，则p²=2q²使p、q同时为偶数，矛盾。','sum((1,1,0,0))',['1','2','3','4'],'将含规律不清的小数改成√2，另改有理小数和立方根数值；保留实数分类。','四种实数的分类与根式辨识。')
add(16,'实数a、b满足a²=b²，且a=3，b<0。|a|+b的值为？',['-6','0','3','6'],'B','b²=9，实数根为±3，b<0取b=-3；|a|+b=3-3=0。','abs(3)-sqrt(3**2)',['-6','0','3','6'],'补a=3及b负条件，将一般绝对值关系改为由平方相等择根后求值。','平方相等、符号条件与绝对值综合。')
add(17,'判断以下陈述，错误的有几个？①0的绝对值最小；②4a-7的相反数为-4a+7；③单项式6πr²的系数为6；④每个有理数都是整数或分数；⑤2⁵x³y²的次数为10。',['1','2','3','4'],'B','①②④正确。π是常数，③的系数应为6π。⑤只计字母指数，次数3+2=5，不计2⁵的指数。所以错误2个。','sum((0!=0,(-4,7)!=(-4,7),6!=6*3.141592653589793,0!=0,3+2!=10))',['1','2','3','4'],'相反数陈述改正确，系数和次数改新单项式6πr²、2⁵x³y²。','需区分数字常数、字母次数和相反数。')
add(18,'有理数a、b、c满足a+b+c=0，abc≠0，且a>|c|>2(-b)。以下结论一定成立的是？',['b>0且c>0','b>0且c<0','b<0且c>0','b<0且c<0'],'D','a>|c|≥0给a>0且a+c>0，故b=-(a+c)<0。又|c|>2(-b)>-b，从而a>-b，a+b>0，c=-(a+b)<0。条件可实现，例如a=5、b=-1、c=-4。','(-(5-4)/abs(-(5-4)),-(5-1)/abs(-(5-1)))',['(1,1)','(1,-1)','(-1,1)','(-1,-1)'],'把中间比较改为|c|>2(-b)，保留零和与绝对值判符号；给出存在性见证，验证表达式取该见证的b、c符号，普遍性由解析的不等式推导证明。','需由两组和的符号分别推断b和c；验算元组表示b、c的符号。')
add(19,'非零实数m、n互为相反数。以下等式中必定成立的有几个？①m+n=0；②|m|=|n|；③m²=n²；④m⁵=n⁵；⑤mn=-m²。',['2','3','4','5'],'C','n=-m。①②③成立；m⁵=-n⁵且m≠0，所以④不成立；mn=-m²，⑤成立。共4个。','sum((1-1==0,abs(1)==abs(-1),1**2==(-1)**2,1**5==(-1)**5,1*(-1)==-1**2))',['2','3','4','5'],'加非零条件，立方改五次幂，乘积表达改-m²，保留相反数幂性质；m=1为通式代入核算，通式证明见解析。','逐项代入n=-m，区分偶次与奇次。')
add(20,'下列四项运算，正确的有几个？①(-3)²=9；②-3(a-2b)=-3a+6b；③-(-1/4)²=1/16；④-[-(-a)]=a。',['1','2','3','4'],'B','①正确，②分配负系数正确；③左边为-1/16，错误；④由内到外化为-a，非a，错误。共2项。','sum(((-3)**2==9,(-3,6)==(-3,6),-(-1/4)**2==1/16,-(-(-1))==1))',['1','2','3','4'],'更换底数、系数、分母并将最后相反数结论改错误。','乘方、负号和分配律同时检查。')

add(21,'计算1/(1×2)+1/(2×3)+1/(3×4)+…+1/(80×81)的值。',['79/80','80/81','81/80','1'],'B','1/[k(k+1)]=1/k-1/(k+1)，逐项相消后只剩1-1/81=80/81。','1-1/81',['79/80','80/81','81/80','1'],'末项1/9900改为1/(80×81)，保留裂项相消。','识别通项并完成连锁相消。')
add(22,'以下四项陈述正确的有几个？①对任意实数a，6a一定为偶数；②单项式-5xy³/8的系数为-5/8，次数为4；③所有无限小数都是无理数；④多项式2x⁴-xy²+3⁶是六次三项式。',['0','1','2','3'],'B','①取a=1/12，则6a=1/2，非偶数；②正确，次数1+3=4；③无限循环小数如0.333…是有理数；④常数3⁶不贡献次数，最高次数4。仅②正确。','sum((6*(1/12)%2==0,(-5/8,1+3)==(-5/8,4),1/3!=1/3,max(4,1+2,0)==6))',['0','1','2','3'],'改单项式和多项式指数，明确a为实数并加入无限小数陈述。','分别核定义并用反例否定全称说法。')
add(23,'单项式4a^(2n+1)b⁶与-7a⁵b^(3m)是同类项，其中字母a、b的指数均为非负整数。求(n+2)³(m-3)⁴。',['16','32','64','128'],'C','同类项要求对应字母指数相等，2n+1=5、3m=6，故n=m=2。原式=(2+2)³(2-3)⁴=4³×1=64。','((5-1)/2+2)**3*(6/3-3)**4',['16','32','64','128'],'更改两个字母的指数关系与最终幂式，仍先比较同类项指数再算幂。','需两次指数匹配与符号乘方。')
add(24,'近似数4.20×10⁴表示一个经过四舍五入的数。它精确到哪一位？',['个位','十位','百位','千位'],'C','4.20末位是百分位，乘10⁴后该位对应0.01×10⁴=100，故精确到百位。末尾的0表示精度，不能省略。','0.01*10**4',['1','10','100','1000'],'由小数末位辨析改为科学记数形式的实际精确位，数值与数量级均修改。','结合有效末位和数量级进行精度转换。')
add(25,'已知a、b为实数，a+b=8、ab=3；u、v为整数，令M=9^u、N=27^v。以下结论正确的有几个？①方程(x-2)^(x+2)=1的整数解只能是x=3（只考虑式子有定义者）；②(x-2)(x²+kx+1)不含x²项时k=2；③a-b=√52；④3^(2u-3v)=M/N。',['1','2','3','4'],'B','①x=-2时(-4)^0=1，也是有定义的解，故错。②展开后x²系数k-2，令其为0得k=2，正确。③(a-b)²=8²-4×3=52，只能得a-b=±√52，两符号都可由交换a、b实现，故错。④M/N=3^(2u)/3^(3v)=3^(2u-3v)，正确。','sum((not (((-2-2)**(-2+2)==1) and -2!=3),2-2==0,((8-sqrt(8**2-4*3))/2-(8+sqrt(8**2-4*3))/2)==sqrt(52),(2,-3)==(2,-3)))',['1','2','3','4'],'原基数4、8改9、27，线性因子x-1改x-2，和与积改8、3，明确整数幂定义。','需反例、系数消去、正负根和指数法则综合。')
add(26,'设m为整数，x=3^(m+1)，y=4+9^m。用x表示y，正确的是？',['y=4+x²/9','y=4+x²/3','y=4+3x','y=4+x/9'],'A','x²=3^(2m+2)=9×9^m，所以9^m=x²/9，y=4+x²/9。x>0，计算无除零问题。','(1/9,0,4)',['(1/9,0,4)','(1/3,0,4)','(0,3,4)','(0,1/9,4)'],'把指数基数2、4改3、9，常数3改4；选项按x²、x、常数项系数元组验算。','需将指数关系转换为代数式。')
add(27,'定义T(x,y)=(3x+y)/(x+y)，其中x+y≠0。求T(1,2)+T(2,3)+…+T(50,51)+T(51,51)+T(51,50)+…+T(2,1)。',['200','201','202','204'],'C','T(x,y)+T(y,x)=(4x+4y)/(x+y)=4。前后共有50对，中央T(51,51)=2，合计50×4+2=202。各分母正，均有定义。','50*(3+1)+(3*51+51)/(51+51)',['200','201','202','204'],'运算分子2x+y改3x+y，端点101改51；保留对称配对和中央项。','从101个分式中发现对称配对，避免逐项算。')
add(28,'整数n满足-16≤n≤-1，且2^n+2^10+1是某个有理数的平方。满足条件的所有n之和为？',['-16','-14','-12','-10'],'C','写n=-k，1≤k≤16。若k为奇数，(1025×2^k+1)/2^k的分子为奇数，既约分母2^k不是整数平方，不可能为有理数平方。若k为偶数，只需整数1025×2^k+1为完全平方。完整检查k=2,4,6,8,10,12,14,16，只有k=12成立，其平方根为2049；原数=(2049/64)²=(32+1/64)²。因此n唯一为-12，和为-12。',None,['-16','-14','-12','-10'],'将2^12改2^10，并明确负整数及完整有限范围，修复原n只写负数的歧义。','结合既约平方分母性质和有界整平方检验。',spec={'kind':'finite_integer_search','variable':'n','lower':-16,'upper':-1,'predicate_expr':'n%2==0 and sqrt((2**10+1)*2**(-n)+1)%1==0','aggregate':'sum','option_exprs':dict(zip('ABCD',['-16','-14','-12','-10'])),'derivation':'偶数n时既约分母为平方，测试整数分子是否完全平方；奇数n分母非平方，均排除。题面明确范围覆盖全部允许n。'})
add(29,'点A₀=(-2,0)连续作轴向平移：第1、2、3、4步依次向上、向右、向下、向左，方向每4步循环；第n步移动2n个单位。求A₁₀₂的坐标。',['(102,102)','(100,102)','(102,100)','(104,102)'],'A','每4步水平净位移4(2j-1)-4(2j)=-4，竖直净位移2(4j-3)-2(4j-1)=-4。100步共25周期，位置(-102,-100)。第101步向上202，第102步向右204，故A₁₀₂=(102,102)。','(-2-4*(102//4)+2*102,-4*(102//4)+2*101)',['(102,102)','(100,102)','(102,100)','(104,102)'],'原图观察后明确四向循环，将起点改(-2,0)、第n步距离改2n；继续求第102点。','需每4步位移求和并处理最后两步。')
add(30,'一个数字幻方用8个不同数-2、4、-4、-8、10、-10、12、16各一次填入8个位置。正方形四顶点按左上、右上、右下、左下依次填-2、c、4、a；正方形上、右、下、左各有一个外顶点，分别填b、d、e、f。每个外顶点与相邻两个正方形顶点组成三角形，且每个三角形顶点数之和都等于正方形顶点数之和。求a+b+c-d。',['6','8','10','12'],'C','记正方形和S=-2+c+4+a=a+c+2。每个外顶点等于与它不相邻的两个正方形顶点之和，故外顶点总和为2S，8数总和为3S=18，S=6。上顶点b=a+4，右顶点d=a-2，于是a+b+c-d=a+c+6=S+4=10。存在填法(a,b,c,d,e,f)=(12,16,-8,10,-10,-4)，所有数恰用一次。即使填法不唯一，目标值由不变量唯一确定。','sum((-2,4,-4,-8,10,-10,12,16))/3+4',['6','8','10','12'],'核看两原图，将全部数字乘2并完整写8位置及四三角形关系；保留幻方等和推理。','需从四等和约束建立总和不变量，且检查存在性与目标唯一性。')
add(31,'将-10、-6、-4、4、6、10、14、16各一次填入8位置。正方形四顶点按左上、右上、右下、左下依次填-10、b、10、a；上、右、下、左四外顶点分别填e、f、d、c。每个外顶点及相邻两正方形顶点的数之和，都等于正方形四数之和。求(d-c)^(a+b)。',['-20¹⁰','20⁵','20¹⁰','-20⁵'],'C','设正方形和S=a+b。四外顶点总和为2S，所以3S=30，a+b=10。下外顶点d=b-10，左外顶点c=b+10，故d-c=-20。目标=(-20)^10=20^10。存在填法(a,b,c,d,e,f)=(4,6,16,-4,14,-6)，全部数恰用一次。偶数次幂取正，目标唯一。','(-20)**(sum((-10,-6,-4,4,6,10,14,16))/3)',['-20**10','20**5','20**10','-20**5'],'看原图并将8数全部乘2，文字写明各位置；独立求幂，修正源解析(-10)^5结果的笔误。','等和不变量与负底数偶数幂结合。')
add(32,'下列各组数中，不相等的一组是？',['√36与6','∛(-125)与-5','|-7|与7','√((-8)²)与-8'],'D','前三组分别为6=6、-5=-5、7=7；最后√((-8)²)=|-8|=8，与-8不等。',None,None,'更换各平方根、立方根和绝对值数值。','区分算术平方根与负数。',spec={'kind':'statement_selection','target_truth':False,'statements':{'A':{'lhs':'sqrt(36)','op':'==','rhs':'6'},'B':{'lhs':'-5','op':'==','rhs':'-5'},'C':{'lhs':'abs(-7)','op':'==','rhs':'7'},'D':{'lhs':'sqrt((-8)**2)','op':'==','rhs':'-8'}}})
add(33,'下列说法中正确的是？',['多项式x²+xy³+1是三次三项式','单项式-2πx²y的系数是-2','单项式5m³n²和-7n²m³是同类项','x+y是单项式'],'C','A最高次数1+3=4，错误；B系数为-2π，错误；C字母及相应指数相同，正确；D有两项，错误。',None,None,'多项式最高次数、含π系数及同类项指数全部改值。','逐项使用整式定义。',spec={'kind':'statement_selection','target_truth':True,'statements':{'A':{'lhs':'max(2,1+3,0)','op':'==','rhs':'3'},'B':{'lhs':'-2*3.141592653589793','op':'==','rhs':'-2'},'C':{'lhs':'(3,2)','op':'==','rhs':'(3,2)'},'D':{'lhs':'2','op':'==','rhs':'1'}}})
add(34,'某食品适宜储藏温度为(-16±3)℃，上下限都适宜。以下哪个温度不适宜？',['-19℃','-17℃','-13℃','-12℃'],'D','区间为[-16-3,-16+3]=[-19,-13]℃，前三温度都在闭区间，-12℃超出上限。',None,None,'中心温度-18改-16，容差2改3，明确端点可用。','闭区间温度范围判断。',spec={'kind':'statement_selection','target_truth':False,'statements':{k:{'lhs':f'-19<={v}<=-13','op':'==','rhs':'True'} for k,v in zip('ABCD',[-19,-17,-13,-12])}})
add(35,'当x=-2，y=-5时，代数式x²-3xy的值为？',['-26','-14','26','34'],'A','先算x²=4、xy=10，故x²-3xy=4-30=-26。','(-2)**2-3*(-2)*(-5)',['-26','-14','26','34'],'x、y分别改-2、-5，xy系数2改3。','负数代入及乘方运算。')
add(36,'某次活动参加人数约为6297.4万人，四舍五入精确到“万”后，用规范科学记数法（1≤系数<10）表示人数。',['6.297×10⁷人','6.298×10⁷人','6.2974×10⁷人','6.297×10⁶人'],'A','6297.4万人精确到万为6297万人，即62970000人=6.297×10⁷人；系数满足1≤6.297<10。','6297*10**4',['6.297*10**7','6.298*10**7','6.2974*10**7','6.297*10**6'],'总量8349.9万改6297.4万，明确先舍入到万再规范科学记数。','数量单位转换与四舍五入。')
add(37,'将-3.2、-0.8、-(-3)、-√10从小到大排列，正确的是？',['-√10<-3.2<-0.8<-(-3)','-3.2<-√10<-0.8<-(-3)','-0.8<-√10<-3.2<-(-3)','-3.2<-0.8<-√10<-(-3)'],'B','3.2²=10.24>10，故3.2>√10；变负后-3.2<-√10。又√10>3，故-√10<-0.8，最后-(-3)=3最大。',None,None,'四个数更改为-3.2、-0.8、3和-√10。','比较根式与负数并注意反号。',spec={'kind':'ordering_values','values':{'a':'-3.2','b':'-0.8','c':'-(-3)','d':'-sqrt(10)'},'option_orders':{'A':['d','a','b','c'],'B':['a','d','b','c'],'C':['b','d','a','c'],'D':['a','b','d','c']}})
add(38,'-(-2027)的相反数是多少？',['2027','-2027','1/2027','-1/2027'],'B','-(-2027)=2027；它的相反数为-2027，相加为0。','-(-(-2027))',['2027','-2027','1/2027','-1/2027'],'2019改2027，保留连续相反数求值。','按由内到外处理负号。')
add(39,'单项式4x⁵y^(2m+1)与7x^(n+2)y⁷的和仍是单项式。求m+n。',['4','5','6','7'],'C','两个非零系数相加不抵消，因此要成为单项式必须为同类项。2m+1=7、n+2=5，得m=n=3，和6。','(7-1)/2+(5-2)',['4','5','6','7'],'x指数3改5、y指数改7及2m+1，保留和为单项式的指数匹配。','由同类项条件解两简单关系。')
add(40,'若收入记为正、支出记为负，某天记录“-4.5万元”，它表示什么？',['收入4.5万元','支出4.5万元','收入45万元','支出0.45万元'],'B','题设正号对应收入，负号对应支出，绝对值4.5对应金额4.5万元，所以为支出4.5万元。','-4.5',['4.5','-4.5','45','-0.45'],'金额-2万元改-4.5万元，明确记录基准；选项以带符号金额核算。','负数表示与正方向相反的意义。')

add(41,'已知4x²-6y+10=22，求2x²-3y-1的值。',['3','5','6','11'],'B','4x²-6y=12，两边除2得2x²-3y=6，所以目标为6-1=5。无需分别求x、y。','(22-10)/2-1',['3','5','6','11'],'改变已知式各系数与常数，仍利用目标与已知的整体倍数关系。','整体代入而不分别解未知数。')
add(42,'下列运算对所有实数a、b恒成立的是？',['5a-2a=3','a⁴-a²=a²','4ab-ba=3ab','a²b-ab²=0'],'C','A左边为3a，非恒为3；B不同类项不能直接减次数；C中ab=ba，所以4ab-ba=3ab；D字母指数不同，非同类项。A取a=0，B取a=2，D取a=1、b=2即可见错。',None,None,'更改系数和幂指数，保留同类项合并辨析。','识别同类项与反例。',spec={'kind':'statement_selection','target_truth':True,'statements':{'A':{'lhs':'5*0-2*0','op':'==','rhs':'3'},'B':{'lhs':'2**4-2**2','op':'==','rhs':'2**2'},'C':{'lhs':'4-1','op':'==','rhs':'3'},'D':{'lhs':'1**2*2-1*2**2','op':'==','rhs':'0'}}})
add(43,'三个人的年龄均为正整数。把每两人的平均年龄加上第三人的年龄，得到的三个数分别为50、63、61。最大年龄与最小年龄相差多少岁？',['13','24','26','28'],'C','设三年龄和S，每个所得数为(S+该第三人年龄)/2。三个所得数之和=2S，所以S=(50+63+61)/2=87；三年龄为13、39、35，均为正整数。最大最小相差39-13=26。','2*(max(50,63,61)-min(50,63,61))',['13','24','26','28'],'三组平均与余下年龄和改50、63、61，补正整数并验证可实现。','需识别年龄总和与三个结果的线性关系。')
add(44,'已知m=(6-x)/2，n=(x+2)/3，p=(1-2x)/4，且m>n>p。求x的取值范围。',['-1/2<x<14/5','x<14/5','x>-1/2','-1/2≤x≤14/5'],'A','m>n给3(6-x)>2(x+2)，所以x<14/5；n>p给4(x+2)>3(1-2x)，所以x>-1/2。取交集为-1/2<x<14/5，两端不取。','((3-8)/(4+6),(18-4)/(3+2),True,True,False,False)',['(-1/2,14/5,True,True,False,False)','(0,14/5,False,True,False,False)','(-1/2,0,True,False,False,False)','(-1/2,14/5,True,True,True,True)'],'改三个仿射式系数及分母，仍分解连锁不等式后取交集；特征为下端、上端、是否有下界、是否有上界、两端是否闭合，无界端位置0仅作未使用空位。','两条不等式与开端点。')
add(45,'商品进价1600元，标价2100元。打折后的售价不得低于进价的105%。若售价=标价×折扣数/10，则允许的最低折扣数是多少？',['7.5折','8折','8.5折','9折'],'B','最低售价1600×1.05=1680元。折扣数d满足2100d/10≥1680，得d≥8。最低为8折。','1600*(1+5/100)/2100*10',['7.5','8','8.5','9'],'进价和标价改1600、2100，明确折扣数与最低值，避免“至多可打”措辞歧义。','百分数利润条件转为一元不等式。')
add(46,'x=-2是关于x的方程3x+4a=10的解，求a。',['1','2','4','5'],'C','代入得-6+4a=10，4a=16，所以a=4。','(10-3*(-2))/4',['1','2','4','5'],'解-1改-2，方程系数2、5与常数3改3、4与10。','先代入已知解再解参数，实际为基础。','基础')
add(47,'以下等式变形中，始终正确的是？',['若x=y，则3x+2=3y+2','若x=y，则x-4=4-y','若2x=8，则x=2','若x=y，则对任意实数a都有x/a=y/a'],'A','等式两边乘3再加2保持相等，A正确。B取x=y=1两边为-3与3；C应得x=4；D允许a=0时除法无定义，所以并非始终正确。',None,None,'变换乘数、移项常数及方程数值，并保留除零限制辨析。','需要检查运算及参数零值。',spec={'kind':'statement_selection','target_truth':True,'statements':{'A':{'lhs':'(3,2)','op':'==','rhs':'(3,2)'},'B':{'lhs':'1-4','op':'==','rhs':'4-1'},'C':{'lhs':'8/2','op':'==','rhs':'2'},'D':{'lhs':'0!=0','op':'==','rhs':'True'}}})
add(48,'方程3(x-2)-c=x+4中常数c被污损。已知该方程的解为x=8，求c。',['4','6','8','10'],'B','代入x=8得3×6-c=12，故c=6。反代后3x-6-6=x+4得2x=16，唯一解x=8。','3*(8-2)-(8+4)',['4','6','8','10'],'方程系数、括号常数和已知解全改；保留从解反求污损常数。','代入后移项恢复常数。')
add(49,'工厂30名工人，每人每天可生产600个面罩主体或800根绑带；一个主体需要2根绑带。设x名工人生产主体，其余生产绑带，要求刚好配套。所列方程正确的是？',['1200x=800(30-x)','600x=1600(30-x)','600x=800(30-x)','1200x=800(30+x)'],'A','主体数600x，需要绑带1200x；实际绑带800(30-x)，因此1200x=800(30-x)。得2000x=24000，x=12，符合0≤x≤30整数要求。其他式子错置配比或人数。','(2*600+800,800*30)',['(2000,24000)','(2200,48000)','(1400,24000)','(400,24000)'],'工人数26改30、生产量800/1000改600/800，仍按一个主体两根配套列式；特征为移项后的x系数与常数。','从人数分配和零件比例建模。')
add(50,'用一根绳子量木条，绳比木条长6尺；把绳对折量木条，木条又比对折后的绳长2尺。绳长为多少尺？',['10尺','12尺','14尺','16尺'],'D','设绳长x、木长y，x-y=6，y-x/2=2。相加得x/2=8，所以x=16、y=10，长度均正，满足两条件。','2*(6+2)',['10','12','14','16'],'余绳4.5改6、短缺1改2，改问绳长；保留两关系建方程组。','需联立长差与对折后的长差。')
add(51,'a是四条互不重合的直线在同一平面内产生的不同交点个数（同一点只计一次）。若关于x的方程ax+4=-14-x有负整数解，满足条件的a有多少个？',['2','3','4','5'],'B','四直线的交点数为0、1、3、4、5或6；2不可能：若不全平行且有三线共点，第四线不经过共点时至少新增2点，总数≥3；若无三线共点，则存在的非平行线对数只能为3、4、5、6。0由全平行、1由全共点实现，其余可由平行或一般位置实现。方程解x=-18/(a+1)，a≥0，故总为负；整数条件a+1整除18。在上述六个数中可行a为0、1、5，对应解-18、-9、-3，共3个。',None,['2','3','4','5'],'修复母题把a既称负整数解又称交点数的歧义，明确a为参数；更改方程常数并保留直线交点可达性与整除综合。','需穷尽四直线交点数量并结合参数整除条件。',spec={'kind':'finite_integer_search','variable':'a','lower':0,'upper':6,'predicate_expr':'a!=2 and 18%(a+1)==0','aggregate':'count','option_exprs':dict(zip('ABCD',['2','3','4','5'])),'derivation':'四不同直线最多6交点，可达集合0,1,3,4,5,6；方程化为x=-18/(a+1)，负整数判据为整除。'})
add(52,'实数a、b、c满足2a+13b+3c=84，3a+9b+c=63。求(3b+c)/(a+2b)。',['1','6/5','5/6','3/2'],'B','设U=a+2b、V=3b+c，原式成为2U+3V=84、3U+V=63。第二式乘3减第一式得7U=105，U=15；V=18。U≠0，所求18/15=6/5。条件有解，如b=0、a=15、c=18。','(63-3*((3*63-84)/7))/((3*63-84)/7)',['1','6/5','5/6','3/2'],'两右端90、72改84、63；仍识别组合未知数解二元线性关系求比。','将三未知数压缩为两组合，注意分母非零。')
add(53,'矩形顶点依次为B(3,2)、C(-3,2)、D(-3,-2)、E(3,-2)。甲、乙同时从A(3,0)出发沿矩形周界运动，甲逆时针每秒1单位，乙顺时针每秒3单位，均匀速连续行进，出发时不计相遇。第2026次相遇的坐标为？',['(0,2)','(-3,0)','(0,-2)','(3,0)'],'B','周长2(6+4)=20，相向相遇间隔20/(1+3)=5秒。甲每次相遇多走5单位，首次到(0,2)，第二次到(-3,0)，第三次到(0,-2)，第四次回A，周期4。2026除4余2，所以为(-3,0)。','(-3,2-(2026%4)*20/(1+3)+2+6)',['(0,2)','(-3,0)','(0,-2)','(3,0)'],'核图后矩形4×2改6×4，起点和顶点完整给出，速度比1:2改1:3，相遇序号改2026。','先相对速度求相遇间隔，再将周界位置按周期转换坐标。')
add(54,'关于x的不等式组为x>2、x≤a-2。四个结论：①若解集为2<x≤4，则a=6；②a=4时不等式组有解；③整数解恰有3个时7≤a<8；④无解时a≤4。正确的有几个？',['1','2','3','4'],'C','①上端a-2=4给a=6；②a=4则x>2且x≤2，无解；③整数只能从3起，恰为3、4、5要求5≤a-2<6，即7≤a<8；④无解当且仅当a-2≤2，即a≤4。所以①③④正确。','sum((6-2==4,4-2>2,(7-2,8-2)==(5,6),4-2<=2))',['1','2','3','4'],'下限1改2、上端a-1改a-2，同步更改结论参数与整数界限。','须处理开端点、整数计数和无解边界。')
add(55,'A、C、B依次位于数轴上，A坐标0、B坐标24，且AC比BC的1/3多4。P、Q分别从A、B同时向数轴正方向运动，速度为3和1.5单位/秒，t≥0。M为线段BP中点，N为线段QM中点。判断：①BC=(5/3)AC；②任意t≥0均有AB=4NQ；③当PB=(1/2)BQ时，t只能为32/5秒。正确的有几个？',['0','1','2','3'],'C','设BC=z，则z+z/3+4=24，z=15、AC=9，①成立。P=3t，Q=24+1.5t，M=12+1.5t，N=18+1.5t，所以NQ=6，②成立，对所有t≥0均不变。③化为|3t-24|=0.75t，分两侧得t=24/3.75=32/5或t=24/2.25=32/3，均非负，故“只能”错误。共2项。','sum(((24-4)/(1+1/3)==(5/3)*(24-(24-4)/(1+1/3)),24==4*(24/4),24/(3-1.5/2)==24/(3+1.5/2)))',['0','1','2','3'],'看原图并明确C在线段内部、数轴正向；AB30改24，比例1/4改1/3，速度2、1改3、1.5，保留中点不变量与绝对值双解。','须坐标化中点及分类解距离方程，检查两非负根。')
add(56,'某方程与x-y=5组成方程组，唯一解为x=3、y=-2。该方程可以是？',['3x-2y=13','x+2y=2','2x+y=5','x+3y=-2'],'A','代入(3,-2)，四式左侧分别为13、-1、4、-3，只有A等于右侧。A与x-y=5的系数行列式-2+3=1≠0，故组成方程组唯一解确为(3,-2)。',None,None,'固定解(2,-1)改(3,-2)，另式常数3改5并改四候选系数。','代入解并检验唯一性。',spec={'kind':'statement_selection','target_truth':True,'statements':{'A':{'lhs':'3*3-2*(-2)','op':'==','rhs':'13'},'B':{'lhs':'3+2*(-2)','op':'==','rhs':'2'},'C':{'lhs':'2*3-2','op':'==','rhs':'5'},'D':{'lhs':'3+3*(-2)','op':'==','rhs':'-2'}}})
add(57,'a=3、b=2是一组满足方程(4/3)ax+by=14、ax-by=7的a、b值（x、y为常数）。求x+6y的算术平方根。',['1','2','3','±3'],'C','代入得4x+2y=14、3x-2y=7，相加得7x=21，x=3；再得y=1，x+6y=9，算术平方根为非负数3，非±3。','sqrt((14+7)/7+6*(14-4*(14+7)/7)/2)',['1','2','3','(3,-3)'],'a、b值2、1改3、2，系数与右端全部调整，目标x+2y改x+6y；明确哪个字母是未知量避免母题表达混淆。','联立求常数后取非负算术平方根，实际为中等。','中等')
add(58,'下列各式中，是二元一次方程的是？',['3x+y=2z','1/x+3y=4','5x-2y=11','x+4y²=7'],'C','二元一次方程含两个未知数，各项次数至多1且是整式方程。A有三未知数，B分母含未知数，D含二次项，只有C合定义。','(2,1,0)',['(3,1,0)','(2,1,1)','(2,1,0)','(2,2,0)'],'改变四候选式所有系数与常数；验证特征为未知数个数、最高总次数、含未知数的分母个数。','按二元一次方程定义辨析。')
add(59,'下列各组中，是二元一次方程组的是？',['x+y=4，y+z=7','2x+y=8，y=3','xy=6，x+y=5','x+y=9，y²=4'],'B','A共三个未知数；C的xy总次数2；D含y²；B两式均整式一次且全组两个未知数，因此B正确。','(2,1,0)',['(3,1,0)','(2,1,0)','(2,2,0)','(2,1,1)'],'改变每组系数常数，验证元组为未知数总数、第一式总次数、第二式总次数超出1的量；D第二式超出1而C第一式超出1。','核两方程与全组未知数范围。')
add(60,'实数m、n满足3m-2n=6。下列哪种符号情况一定不可能？',['m>0且n>0','m>0且n<0','m<0且n>0','m<0且n<0'],'C','m<0、n>0时3m-2n<0，不能为6。其余分别有见证(m,n)=(4,3)、(1,-1.5)、(-2,-6)，都代入得6，所以只有C不可能。',None,None,'系数2、-3和右端3改3、-2与6；保留按两变量符号判断正右端可否实现。','符号分析加三个存在见证。',spec={'kind':'statement_selection','target_truth':False,'statements':{'A':{'lhs':'3*4-2*3','op':'==','rhs':'6'},'B':{'lhs':'3*1-2*(-1.5)','op':'==','rhs':'6'},'C':{'lhs':'3*(-1)-2*1','op':'>','rhs':'0'},'D':{'lhs':'3*(-2)-2*(-6)','op':'==','rhs':'6'}}})

add(61,'下列方程中，是二元一次方程的是？',['1/(x+y)=2','2x-y=xy','x-3/y=6','4x=7y+1'],'D','A与C原式分母含未知数，不是整式方程；B的xy总次数2；D整理为4x-7y=1，是二元一次方程。判断依据原方程形式，不将分式方程清分母后冒充定义。','(2,1,0,0)',['(2,1,1,2)','(2,2,0,0)','(2,1,1,1)','(2,1,0,0)'],'候选系数常数改变，最后式x=y改4x=7y+1；特征为未知数数、最高字母总次数、含变量分母数、该分母中项数。','检验定义并区分原式与清分母式。')
add(62,'实数x、y满足x>y。以下不等式一定成立的是？',['-4x+1>-4y+1','3x-7>3y-7','x+5<y+5','-2x-3>-2y-3'],'B','等式两侧同时乘正数3，再减7保序，B正确；乘负数-4或-2应反向，A、D错；加5应仍为>，C错。',None,None,'替换四组系数与平移常数，仍检查不等式变形保序、反序。','直接使用不等式基本性质。',spec={'kind':'affine_inequality_implication','options':{'A':{'factor':-4,'shift':1,'relation':'>'},'B':{'factor':3,'shift':-7,'relation':'>'},'C':{'factor':1,'shift':5,'relation':'<'},'D':{'factor':-2,'shift':-3,'relation':'>'}}})
add(63,'下列等式变形，错误的是？',['若a=b，则5a+2=5b+2','若a=b，则a(c+1)²=b(c+1)²','若a/(c+1)²=b/(c+1)²且c≠-1，则a=b','若a(c+1)²=b(c+1)²，则a=b'],'D','A、B对相等两边作相同加乘运算，正确。C分母非零，可以乘(c+1)²，正确。D若c=-1，两边恒为0，不能推出a=b，例如a=1、b=2，故D错误。',None,None,'乘除因子c²改(c+1)²，排除点相应从0改-1，保留等式非零条件辨析。','注意乘零的信息丢失。',spec={'kind':'statement_selection','target_truth':False,'statements':{'A':{'lhs':'(5,2)','op':'==','rhs':'(5,2)'},'B':{'lhs':'(1,2,1)','op':'==','rhs':'(1,2,1)'},'C':{'lhs':'(-1+1)==0','op':'==','rhs':'True'},'D':{'lhs':'1','op':'==','rhs':'2'}}})
add(64,'为了解某城区5000名七年级学生的阅读习惯（其中女生2500人，某一所学校七年级学生600人），计划调查200人。下列方式最适合获得有代表性的样本的是？',['在该一所学校的600人中随机抽200人','只在全城区2500名女生中随机抽200人','在全城区5000名七年级学生名单中随机抽200人','取全城区名单最前面的200人'],'C','总体是全城区5000名七年级学生。C的抽样范围覆盖全体且随机；A只覆盖一校，B只覆盖女生，D未随机且名单顺序可能有偏差。选择C。','(5000,200,True)',['(600,200,True)','(2500,200,True)','(5000,200,True)','(5000,200,False)'],'总体8000改5000、样本180改200，补候选抽样框大小并改调查主题；特征为抽样框人数、样本人数、是否随机。','需同时检查随机性和覆盖总体的代表性。')
add(65,'20名学生每人只选择一种最喜欢的节目：A新闻、B体育、C动画、D娱乐。记录为A B A C D B A D C B A D A B C D A B A C。喜欢新闻的学生占全体的百分比为？',['25%','30%','35%','40%'],'C','A出现7次，全体20人，所占比例7/20=0.35=35%。各类计数A7、B5、C4、D4，总数20。','7/(7+5+4+4)*100',['25','30','35','40'],'将40条原记录改成20条新数据，明确每人一选，并改问新闻人数百分比。','需准确频数统计并转换百分数。')
add(66,'为了解4800名学生的数学考试成绩，随机抽取240名学生的成绩统计。判断：①这4800名学生的数学成绩全体为总体；②每名学生的数学成绩为个体；③抽到的240名学生本人构成成绩样本；④样本容量为240。正确的有几个？',['1','2','3','4'],'C','总体和个体都是调查变量“数学成绩”，①②正确。样本是抽到240名学生的成绩，不是学生本人，③错。样本容量是数量240，不带单位，④正确，共3项。',None,['1','2','3','4'],'总体6000、样本200改4800、240，将样本对象故意改为人以检验人和观测值区别。','同时核总体、个体、样本对象和容量。',spec={'kind':'statistical_statement_count','population_size':4800,'sample_size':240,'statements':[{'claimed_role':'population','object_kind':'measurement_values','size':4800},{'claimed_role':'individual','object_kind':'measurement_value','size':1},{'claimed_role':'sample','object_kind':'persons','size':240},{'claimed_role':'sample_size','object_kind':'count','value':240}],'option_exprs':dict(zip('ABCD',['1','2','3','4']))})
add(67,'问卷调查“你最喜欢以下哪一种运动”，每人只能选一项。候选标签为①球类运动，②篮球，③排球，④足球，⑤游泳，⑥水上运动。要选择四项且各项不能有包含关系，应选择哪组？',['①②③④','②③④⑤','①②⑤⑥','②③⑤⑥'],'B','球类运动包含篮球、排球、足球，水上运动包含游泳。A中①包含②③④，C中①包含②且⑥包含⑤，D中⑥包含⑤。B四项都为具体不同运动，没有包含关系，故合理。','(0,0,4)',['(1,3,3)','(0,0,4)','(2,2,2)','(1,1,3)'],'家电分类改运动分类，保留调查项不应上下位交叉；特征为宽类别项数、包含关系对数、具体运动项数，目标要求0宽类0包含4具体项。','理解单选问卷不能出现包含关系。')
add(68,'为了解1.2万名考生的数学成绩，抽取1500名考生的数学成绩统计。这个调查的样本是什么？',['1.2万名考生的数学成绩全体','每一名考生的数学成绩','所抽1500名考生的数学成绩','1500这个数'],'C','样本是总体中被抽出的部分观测值，所以是所抽1500名考生的数学成绩；总体为12000个成绩，个体为一个成绩，样本容量为1500而不是样本本身。','(1500,True)',['(12000,True)','(1,True)','(1500,True)','(1500,False)'],'总体1.6万改1.2万、样本2000改1500；特征为成绩记录数、是否为观测值集合（D是容量数）。','区分样本与样本容量。')
add(69,'生产线上当天有120个待装入救生设备的关键阀门，每个阀门均可进行无损检测。若规定所有阀门必须确认合格，最合适的检测数量为？',['随机抽12个','随机抽30个','随机抽60个','检测全部120个'],'D','每件必须确认合格，而且检查不损坏产品，抽样无法确认未检件，所以应全面检查120个。','120',['12','30','60','120'],'将战斗机零件场景改救生设备阀门，明确120件、无损检测与每件必须合格，改问合理检查数量。','判断全面调查适用场景。')
add(70,'统计某学生一天24小时中睡眠、上课、运动及其他活动各占总时间的百分比。要直观表示各部分在一天中所占的比例，最适合哪一种统计图？',['条形图','折线图','扇形图','直方图'],'C','这里关注各部分相对总体的比例，各比例和为100%。扇形统计图的圆表示整体，各扇形面积比例表示部分所占百分比，故选择扇形图。','(360,True,False,False)',['(0,False,False,False)','(0,False,True,False)','(360,True,False,False)','(0,False,False,True)'],'由笼统一天时间分配改明确24小时及百分比，保留选择适合表达整体占比的图；特征为整体圆周角、是否按面积比例编码、是否主要表达连续趋势，第4特征为是否按连续组距展示频数，直方图为True。','识别部分与整体占比的展示目的。')

def selfcheck():
 records=[]
 for i,q in enumerate(rows,1):
  errors=[]
  matches,detail=check_spec(q['verification_spec'])
  if matches!=[q['answer']]:errors.append('answer mismatch')
  if q['parent_id']!=P[i-1]['id']:errors.append('parent order mismatch')
  if q['family_id']!=P[i-1]['family_id']:errors.append('family mismatch')
  if len(set(q['options'].values()))!=4:errors.append('duplicate option text')
  if q['input_modality']!='text' or q['image_assets']:errors.append('not text')
  if any(x in q['question'] for x in ['如图','ImageHere','<img']):errors.append('unprovided diagram reference')
  records.append({'id':q['id'],'passed':not errors,'errors':errors,'detail':detail,'content_sha256':hashlib.sha256(json.dumps({k:q[k] for k in ['question','options','answer','solution']},ensure_ascii=False,sort_keys=True,separators=(',',':')).encode('utf-8')).hexdigest()})
 report={'agent':'finish_variants_g7','model':'inherited_parent_model','count':len(rows),'passed':sum(r['passed'] for r in records),'failed':sum(not r['passed'] for r in records),'difficulty':dict(Counter(q['difficulty'] for q in rows)),'scope':'生成结构与显式算式自检，不是独立复核或正式数学批准。特征编码的数学语义及概念证明见各题解析，需交叉审查。','records':records}
 (OUT/'selfcheck_g7.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
